// The radar's background map (src/map_data.c, generated by tools/make_map.py from
// OpenStreetMap). Points are 16-bit, in `unit_m` metres east and north of the map's origin.
#pragma once

#include <stdint.h>

enum { MAP_COAST, MAP_MOTORWAY, MAP_TRUNK, MAP_PRIMARY, MAP_RUNWAY };

typedef struct {
    uint32_t start;         // first point, in map.xy (pairs)
    uint16_t n;             // points
    uint8_t cls;            // MAP_*
    int16_t box[4];         // min x, min y, max x, max y
} map_line_t;

typedef struct {
    const char *name;
    int16_t x, y;
    uint8_t rank;           // 0 city or big town, 1 town over 15,000 people, 2 smaller
} map_place_t;

typedef struct {
    double origin_lat, origin_lon;
    float unit_m;
    const int16_t *xy;
    const map_line_t *lines;
    uint32_t line_count;
    const map_place_t *places;
    uint32_t place_count;
} map_t;

extern const map_t map;
